var i=`1369-hallacas`;var n=`world-1369`;var t=`VE`;var s=`south-america`;var r=8;var o=176;var l={en:`Hallacas`,ua:`Гальякас`};var h={en:`Hallacas is a dish from Venezuela featuring masa harina, achiote paste, beef chuck, pork shoulder. This home-sized recipe records each ingredient at the step where it is used. Banana-leaf hallacas are a home preparation; Christmas traditions use carefully folded leaves and many filling variations.`,ua:`Гальякас, страва кухні країни Венесуела з такими основними складниками: маса харіна, паста ачіоте, яловича лопатка, свиняча лопатка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Домашні гальякас у банановому листі; різдвяні традиції мають складне складання й багато варіантів начинки.`};var d=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:17,i:[[`masa-harina`,540,`g`],[`lard`,150,`g`],[`chicken-stock`,460,`ml`],[`achiote-paste`,35,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`beef-chuck`,550,`g`],[`pork-shoulder`,400,`g`],[`yellow-onion`,160,`g`],[`garlic`,4,`clove`],[`green-olives`,100,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[[`banana-leaf`,10,`leaf`]]},{en:`Cook the listed ingredients in simmering water for about 105 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 105 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:105,i:[[`water`,1750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`raisin`,75,`g`]]}];var g={slug:i,id:n,country:`VE`,region:s,servings:8,minutes:176,title:l,text:h,steps:d};export{t as country,g as default,n as id,o as minutes,s as region,r as servings,i as slug,d as steps,h as text,l as title};